import type { ReactNode } from "react";

import type { Language } from "../../content/copy";
import { copyFor } from "../../content/copy";
import type { SessionPhase } from "../../application/session/session-machine";
import { Button } from "../primitives/Button";

interface AppChromeProps {
  readonly language: Language;
  readonly onLanguageChange: (language: Language) => void;
  readonly reducedMotion: boolean;
  readonly onReducedMotionChange: (enabled: boolean) => void;
  readonly phase: SessionPhase;
  readonly simulated: boolean;
  readonly cameraActive: boolean;
  readonly onStop: () => void;
  readonly children: ReactNode;
}

const phaseNumbers: Partial<Record<SessionPhase, number>> = {
  disclosure: 1,
  permission: 2,
  mode: 3,
  safety: 4,
  calibrating: 5,
  tutorial: 6,
  countdown: 7,
  playing: 8,
  cooldown: 9,
  completing: 10,
  result: 11,
};

export function AppChrome({
  language,
  onLanguageChange,
  reducedMotion,
  onReducedMotionChange,
  phase,
  simulated,
  cameraActive,
  onStop,
  children,
}: AppChromeProps) {
  const copy = copyFor(language);
  const phaseNumber = phaseNumbers[phase];

  return (
    <div
      className="app-shell"
      data-reduced-motion={reducedMotion ? "true" : "false"}
    >
      <header className="app-header">
        <a className="wordmark" href="/" aria-label={`${copy.brand} home`}>
          <span>{copy.brand}</span>
          <small>{copy.brandRomanized}</small>
        </a>
        <div className="app-header__status">
          <span
            className="privacy-indicator"
            data-camera-active={cameraActive ? "true" : "false"}
          >
            <span className="privacy-indicator__dot" />
            {cameraActive ? copy.cameraActive : copy.localOnly}
          </span>
          {simulated ? (
            <strong className="simulation-badge">{copy.simulated}</strong>
          ) : null}
          {phaseNumber === undefined ? null : (
            <span className="phase-number" aria-label={`Step ${phaseNumber}`}>
              {String(phaseNumber).padStart(2, "0")} / 11
            </span>
          )}
        </div>
        <div className="app-header__controls">
          <Button
            aria-pressed={reducedMotion}
            onClick={() => {
              onReducedMotionChange(!reducedMotion);
            }}
            variant="quiet"
          >
            {language === "zh" ? "减少动态" : "Reduce motion"}
          </Button>
          <Button
            onClick={() => {
              onLanguageChange(language === "zh" ? "en" : "zh");
            }}
            variant="quiet"
          >
            {language === "zh" ? "English" : "简体中文"}
          </Button>
          {phase === "idle" || phase === "result" ? null : (
            <Button onClick={onStop} variant="secondary">
              {copy.stop}
            </Button>
          )}
        </div>
      </header>
      {children}
    </div>
  );
}
